export const discountCodes = pgTable("discount_codes", {
	id: uuid().defaultRandom().primaryKey().notNull(),
	code: text().notNull(),
	description: text(),
	campaign: text(),
	kind: text().notNull(),
	percentBps: integer("percent_bps"),
	amountKobo: integer("amount_kobo"),
	minSubtotalKobo: integer("min_subtotal_kobo").default(0).notNull(),
	maxDiscountKobo: integer("max_discount_kobo"),
	firstTimeOnly: boolean("first_time_only").default(false).notNull(),
	startsAt: timestamp("starts_at", { withTimezone: true, mode: 'string' }),
	endsAt: timestamp("ends_at", { withTimezone: true, mode: 'string' }),
	usageLimit: integer("usage_limit"),
	usedCount: integer("used_count").default(0).notNull(),
	perCustomerLimit: integer("per_customer_limit"),
	enabled: boolean().default(true).notNull(),
	createdAt: timestamp("created_at", { withTimezone: true, mode: 'string' }).defaultNow().notNull(),
	updatedAt: timestamp("updated_at", { withTimezone: true, mode: 'string' }).defaultNow().notNull(),
}, (table) => [
	index("discount_codes_campaign_idx").using("btree", table.campaign.asc().nullsLast().op("text_ops")),
	uniqueIndex("discount_codes_code_key").using("btree", sql`upper(code)`),
	index("discount_codes_enabled_idx").using("btree", table.enabled.asc().nullsLast().op("timestamptz_ops"), table.startsAt.asc().nullsLast().op("bool_ops"), table.endsAt.asc().nullsLast().op("bool_ops")),
	check("discount_codes_amount_kobo_check", sql`amount_kobo >= 0`),
	check("discount_codes_kind_check", sql`kind = ANY (ARRAY['percent'::text, 'fixed'::text, 'free_shipping'::text])`),
	check("discount_codes_max_discount_kobo_check", sql`max_discount_kobo >= 0`),
	check("discount_codes_min_subtotal_kobo_check", sql`min_subtotal_kobo >= 0`),
	check("discount_codes_per_customer_limit_check", sql`(per_customer_limit IS NULL) OR (per_customer_limit > 0)`),
	check("discount_codes_percent_bps_check", sql`(percent_bps >= 0) AND (percent_bps <= 10000)`),
	check("discount_codes_usage_limit_check", sql`(usage_limit IS NULL) OR (usage_limit > 0)`),
	check("discount_codes_used_count_check", sql`used_count >= 0`),
	check("discount_codes_value_matches_kind", sql`((kind = 'percent'::text) AND (percent_bps IS NOT NULL)) OR ((kind = 'fixed'::text) AND (amount_kobo IS NOT NULL)) OR (kind = 'free_shipping'::text)`),
]);

