export const products = pgTable("products", {
	id: uuid().defaultRandom().primaryKey().notNull(),
	name: text().notNull(),
	slug: text().notNull(),
	description: text(),
	price: integer().notNull(),
	currency: text().default('NGN').notNull(),
	categoryId: uuid("category_id"),
	status: productStatus().default('draft').notNull(),
	featured: boolean().default(false).notNull(),
	/**
	 * Whether this product appears in the Lookbook.
	 *
	 * The lookbook is an editorial surface, not a catalogue dump: it previously
	 * showed "the first eight published products that happen to have an image",
	 * which meant its contents changed whenever anything was added and no one
	 * could choose what appeared. This is the rule now, and it is the admin's to
	 * set — deliberately separate from `featured`, which drives the homepage row,
	 * so a piece can headline the shop without being campaign photography.
	 */
	lookbook: boolean().default(false).notNull(),
	createdAt: timestamp("created_at", { withTimezone: true, mode: 'string' }).defaultNow().notNull(),
	updatedAt: timestamp("updated_at", { withTimezone: true, mode: 'string' }).defaultNow().notNull(),
	weightGrams: integer("weight_grams").default(0).notNull(),
	weightUnit: text("weight_unit").default('g').notNull(),
	fitType: text("fit_type").default('regular').notNull(),
	modelHeightCm: integer("model_height_cm"),
	modelWeightKg: integer("model_weight_kg"),
	modelSize: text("model_size"),
	ratingSum: integer("rating_sum").default(0).notNull(),
	ratingCount: integer("rating_count").default(0).notNull(),
}, (table) => [
	index("products_category_idx").using("btree", table.categoryId.asc().nullsLast().op("uuid_ops")),
	index("products_featured_idx").using("btree", table.featured.asc().nullsLast().op("bool_ops")).where(sql`featured`),
	index("products_fit_type_idx").using("btree", table.fitType.asc().nullsLast().op("text_ops")),
	index("products_status_idx").using("btree", table.status.asc().nullsLast().op("enum_ops")),
	foreignKey({
			columns: [table.categoryId],
			foreignColumns: [categories.id],
			name: "products_category_id_fkey"
		}).onDelete("set null"),
	unique("products_slug_key").on(table.slug),
	check("products_fit_type_check", sql`fit_type = ANY (ARRAY['slim'::text, 'regular'::text, 'relaxed'::text, 'oversized'::text])`),
	check("products_model_height_cm_check", sql`(model_height_cm IS NULL) OR ((model_height_cm >= 100) AND (model_height_cm <= 250))`),
	check("products_model_weight_kg_check", sql`(model_weight_kg IS NULL) OR ((model_weight_kg >= 25) AND (model_weight_kg <= 250))`),
	check("products_price_check", sql`price >= 0`),
	check("products_weight_grams_check", sql`weight_grams >= 0`),
	check("products_weight_unit_check", sql`weight_unit = ANY (ARRAY['g'::text, 'kg'::text])`),
]);

