export const shippingSettings = pgTable("shipping_settings", {
	id: boolean().default(true).primaryKey().notNull(),
	/**
	 * Exchange rates, expressed as NAIRA PER ONE UNIT of the foreign currency.
	 *
	 * NGN is the base: every catalogue price is stored in kobo, and a foreign
	 * price is derived as `kobo / (rate * 100)`. Storing it this way round means
	 * the number an admin types is the one they read in the news ("1600 naira to
	 * the dollar"), rather than its reciprocal.
	 *
	 * Integers, not decimals: naira-per-unit is in the thousands, so whole naira
	 * is finer precision than any FX desk quotes, and it keeps the money maths
	 * free of floating point.
	 */
	ngnPerUsd: integer("ngn_per_usd").default(1600).notNull(),
	ngnPerEur: integer("ngn_per_eur").default(1750).notNull(),
	ngnPerGbp: integer("ngn_per_gbp").default(2050).notNull(),
	/**
	 * Whether those rates actually price the storefront.
	 *
	 * OFF by default, and deliberately so. Until this is switched on the app uses
	 * its original "leading value" rule (₦300,000 reads as $300), which is NOT a
	 * conversion. Turning it on re-prices every non-NGN listing in one step — at
	 * 1600, that same garment becomes $187.50 — so it is an explicit decision an
	 * admin makes with the numbers in front of them, never a silent default.
	 */
	fxEnabled: boolean("fx_enabled").default(false).notNull(),
	updatedAt: timestamp("updated_at", { withTimezone: true, mode: 'string' }).defaultNow().notNull(),
	rateMode: text("rate_mode").default('auto').notNull(),
	rateSource: text("rate_source"),
	rateUpdatedAt: timestamp("rate_updated_at", { withTimezone: true, mode: 'string' }),
	taxRateBps: integer("tax_rate_bps").default(0).notNull(),
	taxLabel: text("tax_label").default('VAT').notNull(),
	taxEnabled: boolean("tax_enabled").default(false).notNull(),
	discountBps: integer("discount_bps").default(0).notNull(),
	discountLabel: text("discount_label").default('Discount').notNull(),
	discountEnabled: boolean("discount_enabled").default(false).notNull(),
	defaultItemWeightGrams: integer("default_item_weight_grams").default(500).notNull(),
}, (table) => [
	check("shipping_settings_id_check", sql`id`),
	check("shipping_settings_default_item_weight_grams_check", sql`default_item_weight_grams >= 0`),
	check("shipping_settings_discount_bps_check", sql`(discount_bps >= 0) AND (discount_bps <= 10000)`),
	check("shipping_settings_ngn_per_usd_check", sql`ngn_per_usd > 0`),
	check("shipping_settings_rate_mode_check", sql`rate_mode = ANY (ARRAY['auto'::text, 'manual'::text])`),
	check("shipping_settings_tax_rate_bps_check", sql`(tax_rate_bps >= 0) AND (tax_rate_bps <= 10000)`),
]);

export const knowledgeChunks = pgTable("knowledge_chunks", {
	id: uuid().defaultRandom().primaryKey().notNull(),
	documentId: uuid("document_id").notNull(),
	content: text().notNull(),
	tsv: tsvector("tsv").generatedAlwaysAs(sql`to_tsvector('english'::regconfig, content)`),
	createdAt: timestamp("created_at", { withTimezone: true, mode: 'string' }).defaultNow().notNull(),
}, (table) => [
	index("knowledge_chunks_doc_idx").using("btree", table.documentId.asc().nullsLast().op("uuid_ops")),
	index("knowledge_chunks_tsv_idx").using("gin", table.tsv.asc().nullsLast().op("tsvector_ops")),
	foreignKey({
			columns: [table.documentId],
			foreignColumns: [knowledgeDocuments.id],
			name: "knowledge_chunks_document_id_fkey"
		}).onDelete("cascade"),
]);

export const newsletterPreferences = pgTable("newsletter_preferences", {
	subscriberId: uuid("subscriber_id").notNull(),
	interest: text().notNull(),
	createdAt: timestamp("created_at", { withTimezone: true, mode: 'string' }).defaultNow().notNull(),
}, (table) => [
	index("newsletter_preferences_interest_idx").using("btree", table.interest.asc().nullsLast().op("text_ops")),
	foreignKey({
			columns: [table.subscriberId],
			foreignColumns: [newsletterSubscribers.id],
			name: "newsletter_preferences_subscriber_id_fkey"
		}).onDelete("cascade"),
	primaryKey({ columns: [table.subscriberId, table.interest], name: "newsletter_preferences_pkey"}),
	check("newsletter_preferences_interest_check", sql`interest = ANY (ARRAY['mens'::text, 'womens'::text, 'childrens'::text, 'shoes'::text, 'accessories'::text, 'luxury'::text])`),
]);
